import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"AI 与手术机器人晨报｜2026-08-12","description":"","frontmatter":{},"headers":[],"relativePath":"2026-08-12-AI与手术机器人晨报.md","filePath":"2026-08-12-AI与手术机器人晨报.md","lastUpdated":1786770226000}'),n={name:"2026-08-12-AI与手术机器人晨报.md"};function i(l,e,s,h,c,d){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="ai-与手术机器人晨报-2026-08-12" tabindex="-1">AI 与手术机器人晨报｜2026-08-12 <a class="header-anchor" href="#ai-与手术机器人晨报-2026-08-12" aria-label="Permalink to &quot;AI 与手术机器人晨报｜2026-08-12&quot;">​</a></h1><blockquote><p><strong>主题：缩短承诺，固定边界——把长期自主拆成可重评估的窗口</strong></p><p>信息窗口：2026-08-10 至 2026-08-12（北京时间）。arXiv 于 8 月 11 日公布新批次，本期只保留四项与 AI Native、远程医疗、手术机器人和机器人学习直接相关的工作。论文均为 8 月 10 日提交的 v1 预印本；除论文作者的实验外，尚无独立复现或临床验证。FDA、Intuitive、CMR Surgical、Johnson &amp; Johnson 等官方渠道在该窗口内没有新的手术机器人监管决定、远程手术临床里程碑或关键产品发布，因此产品/监管部分刻意缩短。</p></blockquote><hr><h2 id="今日摘要" tabindex="-1">今日摘要 <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;今日摘要&quot;">​</a></h2><ol><li><strong>Agent 安全不应靠一次写死的 system prompt，而应靠可归因、可回滚的局部演化。</strong> SHE 将 harness 拆成 System Prompt、Rule Bank、Safety Memory 和 Tool Policy；只有候选修改同时提高安全且不降低效用才升级。其 Agent-SafetyBench 平均攻击成功率从初始 harness 的 8.6% 降至 5.5%，攻击下效用从 33.5% 升至 47.6%。</li><li><strong>实时医疗 AI 的突破点不是单模型更大，而是不同时间预算的 Agent 异步协作。</strong> AMIE Video 用低延迟 Talker、深推理 Planner 和持续感知 Perception 分离“现在要回应”与“稍后要想清楚”。在 100 个模拟临床情景的随机 OSCE 中，评审将其病史采集、诊断、管理和视频观察评为与基层医生相当或更好，但医生在关系建立与合作感上仍占优。</li><li><strong>手术机器人 action chunk 不该一次执行到底。</strong> TDHD 对同一 flow-matching 策略施加小噪声扰动，比较两条未来轨迹的逐步分歧；绝对分歧或相对跳变超阈值就提前截断并重规划。真实双臂仿 da Vinci 平台上，组织操作端到端成功率由 55% 提升到 80%，针操作仅由 55% 提升到 60%。</li><li><strong>机器人学习的基础设施正在从“每个模型配一套环境”转向稳定契约。</strong> XPolicyLab 用统一 observation/action/trajectory schema 和隔离式 client/server 把 N 个策略接 M 个环境的集成成本从 O(NM) 改为 O(N+M)，已接入 42 个策略；但其真实双臂榜单最好策略成功率也只有 12.8%，标准化让差距可测量，并没有消除 sim-to-real。</li><li><strong>交叉结论：高风险自主系统的可靠性来自两件事——固定接口边界，缩短不可逆承诺。</strong> SHE 限制一次修改能动哪些安全部件；AMIE 限制不同 Agent 的时间预算与职责；TDHD 限制一次开放环执行多远；XPolicyLab 限制策略与环境如何交换状态。四者都没有要求一个模块“一次做对全部事情”。</li></ol><hr><h2 id="ai-前沿" tabindex="-1">AI 前沿 <a class="header-anchor" href="#ai-前沿" aria-label="Permalink to &quot;AI 前沿&quot;">​</a></h2><h3 id="_1-she-让-agent-harness-从失败轨迹中做有边界的局部演化" tabindex="-1">1. SHE：让 Agent harness 从失败轨迹中做有边界的局部演化 <a class="header-anchor" href="#_1-she-让-agent-harness-从失败轨迹中做有边界的局部演化" aria-label="Permalink to &quot;1. SHE：让 Agent harness 从失败轨迹中做有边界的局部演化&quot;">​</a></h3><p><strong>事实。</strong> SHE 将 Agent harness 表示为四个可编辑但职责分离的对象：System Prompt 定义全局行为契约，Rule Bank 表达风险条件与干预，Safety Memory 保存反复无法修复的失败经验，Tool Policy 约束工具权限与运行时执行。一次 rollout 失败后，系统先做风险诊断和责任路由，只修改被归因的 artifact；候选修改要经过 schema/有效性检查，并且只有在安全指标提高、正常任务效用不下降时才成为新版本，否则恢复上一 best harness。<a href="https://arxiv.org/abs/2608.09885" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2608.09885" target="_blank" rel="noreferrer">HTML 全文</a>｜<a href="https://github.com/RainbowQTT/SHE" target="_blank" rel="noreferrer">作者代码</a></p><p><strong>作者结果。</strong> 论文从 Agent-SafetyBench 官方 2,000 个任务中取前 200 个，15 个用于 20 轮 evolution，185 个只用于最终评估；每个任务包含 clean 与 context poisoning、indirect injection、tool tampering、memory injection、composite attack 五类攻击条件。相较初始解耦 harness，演化后平均攻击成功率从 8.6% 降至 5.5%，clean unsafe behavior rate 从 25.7% 降至 19.8%，攻击下效用从 33.5% 升至 47.6%。在完全留出的 AgentHarm 上，Harm Score 从 19.8% 降至 9.8%，拒绝有害任务从 78.4% 升至 86.4%。</p><p><strong>边界。</strong> evolution 只使用 15 个任务、两次 rollout 重复，核心 judge 与演化模型仍是 LLM；论文用温度 0 降低随机性，却不能消除评审模型偏差。安全与效用由固定 benchmark 协议定义，候选修改可能学到评估器而非真实风险。它证明了“局部、受门控的 harness 更新”比静态规则更有潜力，不证明 harness 可以无人监管地自我修改。</p><p><strong>推断。</strong> 对 AI Native 系统，安全修复应落到明确 owner，而不是把所有失败都追加进一个长 prompt。最小对象可拆成 <code>behavior contract / task rules / incident memory / tool authority</code>，每次修改都附触发轨迹、目标 artifact、回归集、效用差异和 rollback id。权限与数据外发边界不能由同一个负责提高任务成功率的 judge 单独批准。</p><h3 id="_2-amie-video-低延迟对话、深推理与持续感知采用不同时间尺度" tabindex="-1">2. AMIE Video：低延迟对话、深推理与持续感知采用不同时间尺度 <a class="header-anchor" href="#_2-amie-video-低延迟对话、深推理与持续感知采用不同时间尺度" aria-label="Permalink to &quot;2. AMIE Video：低延迟对话、深推理与持续感知采用不同时间尺度&quot;">​</a></h3><p><strong>事实。</strong> Google Research 与 Google DeepMind 的 AMIE Video 基于 Gemini 3 Flash / 3.1 Pro，由三个异步 Agent 组成。Talker 只看最近 5 秒视频，以较小计算预算负责自然打断和低延迟回应；Planner 维护症状摘要、鉴别诊断、管理计划和对话目标，深推理最多每 10 秒触发一次；Perception 处理更长的音视频窗口并持久记录咳嗽、姿态、语速等临床线索。Talker 始终读取另两个 Agent 的最新状态，而不等待它们完成。<a href="https://arxiv.org/abs/2608.09861" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2608.09861" target="_blank" rel="noreferrer">HTML 全文</a></p><p><strong>作者结果。</strong> 主研究包含 100 个带音视频线索和引导式查体的模拟情景、15 名专业 patient actors、10 名实际问诊的美国基层医生和 20 名独立临床评审；论文摘要把两组医生合计为 30 名。临床评审认为 AMIE Video 在病史采集、诊断、管理、身体观察与检查上与医生相当或更好。Patient actors 更偏好 AMIE 的评估与解释方式，但在 rapport 和 partnership building 上更偏好医生；视频版相对文字版在沟通有效性、便利性和“被理解感”上更受偏好。</p><p><strong>边界。</strong> 这是 OSCE 模拟问诊，不是真实患者或前瞻临床试验；研究由系统开发方完成。论文明确指出模型对精细解剖位置、细微情绪和高频运动仍不稳定。异步架构还引入新的状态陈旧风险：Talker 可能在 Planner 或 Perception 更新完成前回应。作者用高层目标、提示和持续处理减轻错位，但没有证明这一风险在真实急症中可接受。</p><p><strong>推断。</strong> 对远程医疗或远程手术辅助，关键不是把视频、语音、术式知识和对话全部塞给一个实时模型，而是把 fast path 与 slow path 分开：fast path 只做低延迟交互和硬安全动作，slow path 做阶段推理、风险累积和复盘；所有输出都带 <code>source_timestamp / state_version / freshness_budget</code>。慢 Agent 的新结论不能静默覆盖已经执行的实时决策，应触发显式协调或升级。</p><hr><h2 id="手术机器人与远程手术" tabindex="-1">手术机器人与远程手术 <a class="header-anchor" href="#手术机器人与远程手术" aria-label="Permalink to &quot;手术机器人与远程手术&quot;">​</a></h2><h3 id="_1-tdhd-用轨迹分歧决定-action-chunk-还能安全执行多远" tabindex="-1">1. TDHD：用轨迹分歧决定 action chunk 还能安全执行多远 <a class="header-anchor" href="#_1-tdhd-用轨迹分歧决定-action-chunk-还能安全执行多远" aria-label="Permalink to &quot;1. TDHD：用轨迹分歧决定 action chunk 还能安全执行多远&quot;">​</a></h3><p><strong>事实。</strong> TDHD 面向生成 action chunk 的 flow-matching VLA。每次推理从初始噪声 <code>z1</code> 生成主轨迹，再用很小扰动 <code>z2 = z1 + εη</code> 生成第二条轨迹；逐步计算两条动作的 L2 分歧。若分歧超过绝对阈值，或相邻步骤的分歧比例突然跳变，就把执行长度截断到当前可靠区间，重新读取视觉状态并规划下一 chunk。视觉语言 encoder 每轮只运行一次，额外成本主要来自较小 action decoder 的第二次生成。<a href="https://arxiv.org/abs/2608.09125" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2608.09125" target="_blank" rel="noreferrer">HTML 全文</a></p><p><strong>作者结果。</strong> 团队在双 RM65-B 机械臂上安装 dVRK 风格末端器械，用外部 RGB-D 与双腕 RGB 相机、双 Geomagic Touch 采集 600 条 30 Hz 遥操作示教：针的 reach/pick/regrasp 和仿组织的 reach/lift/resection 各 100 条。五种方法、六个子任务、每项 20 次，共 600 次真实机器人试验。<code>π0.5 + TDHD</code> 的针操作端到端成功率为 60%，基线 <code>π0.5</code> 为 55%；组织操作为 80% 对 55%。10 次重复的消融中，TDHD 相对最佳固定 horizon 把 needle pick 从 80% 提到 90%、tissue resection 从 60% 提到 70%，但 needle regrasp 均为 50%。</p><p><strong>边界。</strong> 数据来自可重复软体 phantom，而非离体/在体组织；每个端到端比例只有 20 次试验，5 个百分点等于 1 次成功差异。轨迹对噪声敏感只是模型不稳定性的 proxy，不是碰撞、组织损伤或控制安全的证明；绝对/相对阈值仍需人工校准。它能决定“何时重规划”，不能替代 RCM、速度、力和工作空间硬约束。</p><p><strong>推断。</strong> 远程手术的自主或辅助动作应把 <code>action horizon</code> 变成运行时变量，而不是模型固定超参数。除策略轨迹分歧外，还应同时纳入网络数据年龄、图像冻结、力/RCM residual 和操作者接管信号；任何硬约束触发都直接进入 hold，而不是仅缩短 chunk。价值最大的测量不是平均成功率，而是“高风险接触阶段比稳定自由运动阶段缩短了多少、是否在损伤前触发”。</p><h3 id="_2-xpolicylab-标准化策略—环境边界-也把-sim-to-real-落差暴露出来" tabindex="-1">2. XPolicyLab：标准化策略—环境边界，也把 sim-to-real 落差暴露出来 <a class="header-anchor" href="#_2-xpolicylab-标准化策略—环境边界-也把-sim-to-real-落差暴露出来" aria-label="Permalink to &quot;2. XPolicyLab：标准化策略—环境边界，也把 sim-to-real 落差暴露出来&quot;">​</a></h3><p><strong>事实。</strong> XPolicyLab 定义统一 observation、action 与 trajectory schema，以及 <code>update_obs / get_action / batch / reset</code> 最小适配器。策略推理与仿真/机器人控制运行在依赖隔离的 client/server 中，可在同机或远端 GPU；请求有唯一 ID，断线重试返回缓存结果而不重复推进有状态策略，server instance 变化则终止当前 trial。项目截至 8 月 8 日接入 42 个 VLA、WAM、diffusion、memory 与 imitation policy，并连接 RoboTwin、RoboDojo 仿真和真实机器人评测。<a href="https://arxiv.org/abs/2608.09892" target="_blank" rel="noreferrer">论文原文</a>｜<a href="https://arxiv.org/html/2608.09892" target="_blank" rel="noreferrer">HTML 全文</a>｜<a href="https://xpolicylab.github.io/" target="_blank" rel="noreferrer">项目页</a>｜<a href="https://github.com/XPolicyLab/XPolicyLab" target="_blank" rel="noreferrer">代码仓库</a></p><p><strong>作者结果。</strong> 六名不熟悉 XPolicyLab 的工程师以交叉顺序完成 <code>π0.5 → RoboDojo</code> 集成：从上游仓库手写中位耗时超过 5 小时，按标准手工接入约 2 小时，用固定 Cursor + Opus 5 和仓库内 agent skills 后约 30 分钟。更重要的是统一评测暴露了泛化缺口：RoboTwin clean 榜首 FastWAM 为 77.8%，随机化后仅 1.9%；真实双臂 18 任务榜首 <code>π0.5</code> 成功率也只有 12.8%，且真实排名只部分跟随仿真。</p><p><strong>边界。</strong> 集成效率实验只有 6 人、一个策略和一个目标环境，并且参与者在三种条件间可能形成熟悉效应；Agent 条件把人工编写代码计为约 0 行，不代表没有人工配置、运行、审查与调试。统一 schema 只能减少接口与依赖噪声，无法标准化真实场景重置、硬件磨损、传感同步和安全监督。</p><p><strong>推断。</strong> 对手术机器人 RL 平台，应先建立稳定的 <code>policy contract</code>，再比较算法：观测字段、相机/坐标系、动作单位、chunk 长度、状态 reset、deadline、幂等重试与 server 重启语义都必须版本化。策略服务器可以远端化，但患者侧硬实时控制、限幅、RCM、急停和最后授权必须留在环境/机器人侧；网络重试绝不能让同一个逻辑动作执行两次。</p><h3 id="_3-产品、临床与监管-本窗口没有新的高价值事实" tabindex="-1">3. 产品、临床与监管：本窗口没有新的高价值事实 <a class="header-anchor" href="#_3-产品、临床与监管-本窗口没有新的高价值事实" aria-label="Permalink to &quot;3. 产品、临床与监管：本窗口没有新的高价值事实&quot;">​</a></h3><p>截至 2026-08-12 早间，FDA CDRH 更新页最新条目仍是 8 月 7 日，且与手术机器人无关；Johnson &amp; Johnson 8 月 10 日的最新公告是投资者会议，最近的 OTTAVA 授权仍是 7 月 22 日。Intuitive 与 CMR Surgical 公开列表也未显示 8 月 10–12 日新增的远程手术临床实施、手术机器人授权或关键产品发布。本期不把旧授权或会议展示重新包装为今日新闻。<a href="https://www.fda.gov/medical-devices/medical-devices-news-and-events/cdrhnew-news-and-updates" target="_blank" rel="noreferrer">FDA CDRH 更新</a>｜<a href="https://www.intuitive.com/en-us/about-us/newsroom" target="_blank" rel="noreferrer">Intuitive Newsroom</a>｜<a href="https://cmrsurgical.com/" target="_blank" rel="noreferrer">CMR Surgical</a>｜<a href="https://www.jnj.com/media-center/press-releases" target="_blank" rel="noreferrer">J&amp;J Press Releases</a></p><hr><h2 id="论文-产品-监管动态" tabindex="-1">论文 / 产品 / 监管动态 <a class="header-anchor" href="#论文-产品-监管动态" aria-label="Permalink to &quot;论文 / 产品 / 监管动态&quot;">​</a></h2><h3 id="论文" tabindex="-1">论文 <a class="header-anchor" href="#论文" aria-label="Permalink to &quot;论文&quot;">​</a></h3><ul><li><strong>AI Native 安全：</strong> SHE 把 harness 更新从“重写大 prompt”变成有责任边界、回归门和回滚状态的局部修改。</li><li><strong>实时医疗 AI：</strong> AMIE Video 用异步多 Agent 解决低延迟交互、深临床推理与持续音视频感知的时间预算冲突。</li><li><strong>手术机器人学习：</strong> TDHD 直接把 action chunk 的开放环长度变成由模型轨迹稳定性决定的运行时量。</li><li><strong>机器人学习基础设施：</strong> XPolicyLab 统一策略与环境契约，并用同一接口同时暴露 clean/randomized、sim/real 的真实差距。</li></ul><h3 id="产品与监管" tabindex="-1">产品与监管 <a class="header-anchor" href="#产品与监管" aria-label="Permalink to &quot;产品与监管&quot;">​</a></h3><p>最近 72 小时没有足以扩写的手术机器人产品、远程手术临床或监管新进展；本期不以旧闻填充。</p><hr><h2 id="对-nathan-当前项目的启示" tabindex="-1">对 Nathan 当前项目的启示 <a class="header-anchor" href="#对-nathan-当前项目的启示" aria-label="Permalink to &quot;对 Nathan 当前项目的启示&quot;">​</a></h2><h3 id="_1-ai-native-把-harness-变成四类独立版本对象" tabindex="-1">1. AI Native：把 harness 变成四类独立版本对象 <a class="header-anchor" href="#_1-ai-native-把-harness-变成四类独立版本对象" aria-label="Permalink to &quot;1. AI Native：把 harness 变成四类独立版本对象&quot;">​</a></h3><p>将行为契约、任务规则、失败记忆和工具权限分开存储；每次候选修改只触碰被归因的对象，并保存失败轨迹、评审指标、版本与 rollback。</p><p><strong>最小实验与完成标准：</strong> 从近期自动化/编码任务选 20 条历史轨迹，人工标注失败属于 context、rule、memory 还是 authority。候选修复必须通过原失败重放、10 条正常任务回归和 5 条相邻攻击；安全提升且任务效用不退化才升级，任何版本可一条命令回退。</p><h3 id="_2-远程手术-建立-fast-slow-hard-三条控制路径" tabindex="-1">2. 远程手术：建立 fast / slow / hard 三条控制路径 <a class="header-anchor" href="#_2-远程手术-建立-fast-slow-hard-三条控制路径" aria-label="Permalink to &quot;2. 远程手术：建立 fast / slow / hard 三条控制路径&quot;">​</a></h3><ul><li><code>fast path</code>：低延迟遥操作、视频/网络状态和局部保护反射。</li><li><code>slow path</code>：阶段推理、风险聚合、策略建议与事件复盘。</li><li><code>hard path</code>：RCM、力/速度限幅、工作空间、急停和患者侧最终授权，不接受生成式更新。</li></ul><p><strong>完成标准：</strong> 所有跨路径消息带单调时间戳、状态版本和 freshness budget；slow path 超时不阻塞 fast path；fast/slow 结论冲突进入明确仲裁状态；hard path 在任何模型或网络失效时仍独立有效。</p><h3 id="_3-手术机器人-vla-让-action-horizon-随阶段和证据变化" tabindex="-1">3. 手术机器人 VLA：让 action horizon 随阶段和证据变化 <a class="header-anchor" href="#_3-手术机器人-vla-让-action-horizon-随阶段和证据变化" aria-label="Permalink to &quot;3. 手术机器人 VLA：让 action horizon 随阶段和证据变化&quot;">​</a></h3><p>离体或 phantom 回放中，对自由运动、接触建立、牵拉、切割、器械交接分别统计轨迹分歧、物理 residual 与最佳重规划点，不用一个固定 chunk 覆盖全程。</p><p><strong>完成标准：</strong> 动态 horizon 在不增加硬约束违规的前提下优于所有固定 horizon；报告 95/99 分位的触发延迟、重规划频率、最短/最长 chunk、阶段条件成功率与误触发，而不只报告平均成功率。</p><h3 id="_4-机器人-rl-先统一-policy-contract-再比较模型" tabindex="-1">4. 机器人 RL：先统一 policy contract，再比较模型 <a class="header-anchor" href="#_4-机器人-rl-先统一-policy-contract-再比较模型" aria-label="Permalink to &quot;4. 机器人 RL：先统一 policy contract，再比较模型&quot;">​</a></h3><p>定义最小 schema：多相机命名与标定、关节/末端坐标系、夹爪单位、动作时间戳、chunk、reset、deadline、幂等 request id、model/server instance id 和安全 envelope。</p><p><strong>完成标准：</strong> 同一个策略 adapter 可在仿真、台架和真实机器人复用；相机通道、单位或坐标系错配在动作下发前被 conformance test 拦截；策略进程重启会终止 episode，断线重试不会重复执行动作。</p><h3 id="_5-远程医疗-手术视频-ai-把-看见-与-说出-分开审计" tabindex="-1">5. 远程医疗/手术视频 AI：把“看见”与“说出”分开审计 <a class="header-anchor" href="#_5-远程医疗-手术视频-ai-把-看见-与-说出-分开审计" aria-label="Permalink to &quot;5. 远程医疗/手术视频 AI：把“看见”与“说出”分开审计&quot;">​</a></h3><p>AMIE 的 Perception/Planner/Talker 分层可迁移为术中观察、风险推理和人机交互三个服务，但术中系统需要比问诊更严格的状态一致性。</p><p><strong>完成标准：</strong> 对咳嗽式瞬时事件、持续组织牵拉、器械遮挡、视频冻结和高频运动分别测试 detection-to-advice 延迟；任何建议能追溯到具体帧窗口、感知版本和推理版本；陈旧状态不得以当前事实呈现。</p><hr><h2 id="值得继续跟踪的问题" tabindex="-1">值得继续跟踪的问题 <a class="header-anchor" href="#值得继续跟踪的问题" aria-label="Permalink to &quot;值得继续跟踪的问题&quot;">​</a></h2><ol><li>SHE 的安全—效用 judge 若本身被 prompt injection 或 benchmark bias 影响，谁来批准 harness 更新？</li><li>哪些安全规则必须永久只读，不能进入 Agent 自动 evolution？</li><li>AMIE 的 Talker 在 Planner/Perception 尚未更新时会怎样表达不确定性，能否避免把陈旧状态说成最新结论？</li><li>实时医疗多 Agent 的跨模块状态需要强一致、因果一致，还是带 freshness budget 的最终一致？</li><li>TDHD 的两轨迹分歧能否预测真实接触风险，还是只是在检测 flow-matching decoder 对噪声的敏感性？</li><li>动态 horizon 与网络 jitter、视频帧率下降、力 residual 联合时，应采用规则仲裁、风险上界还是学习式融合？</li><li><code>π0.5 + TDHD</code> 的针任务只多成功 1/20 次；扩大样本、换器械/组织/相机后效果是否仍成立？</li><li>XPolicyLab 的统一 schema 如何表达 RCM、器械轴约束、主从缩放与控制权等手术特有语义？</li><li>策略推理远端化时，request id、动作序号、数据年龄和患者侧执行确认怎样组成 exactly-once/at-most-once 契约？</li><li>同一策略在 clean 仿真、随机化仿真和真实平台的失败能否映射为统一 failure taxonomy，直接驱动下一轮数据采集？</li></ol><hr><h2 id="来源链接" tabindex="-1">来源链接 <a class="header-anchor" href="#来源链接" aria-label="Permalink to &quot;来源链接&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2608.09885" target="_blank" rel="noreferrer">arXiv：SHE——轨迹驱动的 Agent 安全 harness 演化</a></li><li><a href="https://arxiv.org/html/2608.09885" target="_blank" rel="noreferrer">arXiv HTML：SHE 的四类 artifact、门控算法与实验表</a></li><li><a href="https://github.com/RainbowQTT/SHE" target="_blank" rel="noreferrer">SHE 作者代码仓库</a></li><li><a href="https://arxiv.org/abs/2608.09861" target="_blank" rel="noreferrer">arXiv：AMIE Video——实时视频医疗 AI</a></li><li><a href="https://arxiv.org/html/2608.09861" target="_blank" rel="noreferrer">arXiv HTML：AMIE 的异步三 Agent 架构、OSCE 与限制</a></li><li><a href="https://arxiv.org/abs/2608.09125" target="_blank" rel="noreferrer">arXiv：TDHD——双臂手术子任务的动态执行 horizon</a></li><li><a href="https://arxiv.org/html/2608.09125" target="_blank" rel="noreferrer">arXiv HTML：TDHD 方法、600 条示教与 600 次机器人试验</a></li><li><a href="https://arxiv.org/abs/2608.09892" target="_blank" rel="noreferrer">arXiv：XPolicyLab——机器人策略统一评估与部署契约</a></li><li><a href="https://arxiv.org/html/2608.09892" target="_blank" rel="noreferrer">arXiv HTML：XPolicyLab 的 42 策略、排行榜与集成实验</a></li><li><a href="https://xpolicylab.github.io/" target="_blank" rel="noreferrer">XPolicyLab 官方项目页</a></li><li><a href="https://github.com/XPolicyLab/XPolicyLab" target="_blank" rel="noreferrer">XPolicyLab 官方代码仓库</a></li><li><a href="https://arxiv.org/list/cs.AI/recent" target="_blank" rel="noreferrer">arXiv：cs.AI 最近提交（核验 8 月 11 日批次）</a></li><li><a href="https://arxiv.org/list/cs.RO/recent" target="_blank" rel="noreferrer">arXiv：cs.RO 最近提交（核验 8 月 11 日批次）</a></li><li><a href="https://www.fda.gov/medical-devices/medical-devices-news-and-events/cdrhnew-news-and-updates" target="_blank" rel="noreferrer">FDA：CDRH News and Updates（核验监管动态）</a></li><li><a href="https://www.intuitive.com/en-us/about-us/newsroom" target="_blank" rel="noreferrer">Intuitive：官方 Newsroom（核验产品与临床动态）</a></li><li><a href="https://cmrsurgical.com/" target="_blank" rel="noreferrer">CMR Surgical：官方网站（核验产品动态）</a></li><li><a href="https://www.jnj.com/media-center/press-releases" target="_blank" rel="noreferrer">Johnson &amp; Johnson：官方 Press Releases（核验 OTTAVA 与最新公告）</a></li><li><a href="https://openai.com/news/" target="_blank" rel="noreferrer">OpenAI：官方 News（核验 AI 产品动态）</a></li><li><a href="https://deepmind.google/blog/" target="_blank" rel="noreferrer">Google DeepMind：官方 News（核验 AI 与机器人动态）</a></li></ul><hr><p><em>事实以链接所示原始来源为准；“作者结果”是论文作者报告的实验数据与解释；“推断”是结合 Nathan 当前 AI Native、远程手术和机器人强化学习方向给出的工程判断。预印本、Agent benchmark、模拟 OSCE、软体 phantom、少量真实机器人试验和新开源基础设施，在独立复现、风险管理、真实患者/组织及临床验证前，均不应外推为医疗安全性或有效性结论。</em></p>',62)])])}const b=a(n,[["render",i]]);export{g as __pageData,b as default};
